import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static int findSpan(List<Integer> positions, int startIdx, int maxTime) {
        int count = 1;
        for (int nextIdx = startIdx + 1; nextIdx < positions.size(); nextIdx++) {
            if (positions.get(nextIdx) - positions.get(startIdx) > maxTime)
                break;
            count++;
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int total = scanner.nextInt();
        List<Integer> positions = new ArrayList<>();
        for (int i = 0; i < total; i++) {
            int val = scanner.nextInt();
            positions.add(val);
        }
        int limitTime = scanner.nextInt();
        Collections.sort(positions);
        int maxLength = 0;
        for (int i = 0; i < positions.size(); i++) {
            int length = findSpan(positions, i, limitTime);
            if (length > maxLength)
                maxLength = length;
        }
        System.out.println(maxLength);
        scanner.close();
    }
}
